<script setup lang="ts">
import type { PublicFeedback } from '~/domain/operations-types'
import { COMPONENTS, formatDemoTime } from '~/domain/selectors'
definePageMeta({ layout: 'workspace' })
useHead({ title: 'Publikasi hasil - UKIN PPG UNJ' })
const u = useUkin(), route = useRoute(), { error, message, act } = useOperationFeedback()
const id = ref(typeof route.query.id === 'string' ? route.query.id : ''), reason = ref(''), confirmed = ref(false), indicators = ref<string[]>([])
const content = ref<PublicFeedback>({ strengths: '', improvements: '', feedback: { perangkat: '', video: '', studi_kasus: '' }, showComponentScores: false })
const rows = computed(() => u.user.value?.role === 'pengelola' ? u.operations.getMonitoring() : [])
const current = computed(() => rows.value.find(r => r.id === id.value))
const history = computed(() => u.user.value?.role === 'pengelola' ? u.operations.getPublications().filter(p => p.attemptId === id.value).reverse() : [])
const preview = ref<ReturnType<typeof u.operations.previewPublication> | null>(null), key = ref('')
watch([id, content], () => { preview.value = null; confirmed.value = false }, { deep: true })
watch(id, () => { indicators.value = []; reason.value = ''; content.value = { strengths: '', improvements: '', feedback: { perangkat: '', video: '', studi_kasus: '' }, showComponentScores: false } })
function prepare() { const p = act(() => u.operations.previewPublication(id.value, content.value), 'Pratinjau siap ditinjau. Hanya isi di bawah yang akan diterima peserta.'); if (p) { preview.value = p; key.value = crypto.randomUUID(); confirmed.value = false } }
function publish() { if (!preview.value) return; act(() => { u.operations.publishResult(id.value, content.value, preview.value!.token, key.value, reason.value, confirmed.value); preview.value = null; confirmed.value = false }, 'Publikasi berversi tersimpan. Peserta pemilik paket dapat melihatnya.') }
async function openCase() { const m = act(() => u.operations.openModeration(id.value, indicators.value, reason.value, current.value?.token ?? '', confirmed.value), 'Kasus moderasi dibuka.'); if (m) await navigateTo({ path: '/app/moderasi', query: { id: m.id } }) }
function withdraw(publicationId: string) { act(() => u.operations.withdrawPublication(publicationId, reason.value, confirmed.value), 'Publikasi ditarik. Versi dan alasannya tetap tercatat.'); confirmed.value = false }
</script>
<template>
  <div class="operations-page"><header><p class="eyebrow">PENGELOLA / PUBLIKASI</p><h1>Terbitkan feedback dengan sadar.</h1><p class="muted">Penilaian selesai belum berarti hasil terlihat peserta. Tinjau kesiapan, tentukan isi publik, lalu konfirmasi.</p></header>
    <label class="op-field">Peserta dan periode<select v-model="id"><option value="">Pilih paket peserta</option><option v-for="r in rows" :key="r.id" :value="r.id">{{ r.participant }} / {{ r.periodName }} / {{ r.publication }}</option></select></label>
    <p v-if="error" class="op-error" role="alert">{{ error }}</p><p v-if="message" class="op-success" role="status">{{ message }}</p>
    <template v-if="current"><section class="op-hero"><div><h2>{{ current.participant }} / Paket v{{ current.evidenceVersion ?? '-' }}</h2><p>{{ current.problems.length ? 'Masih ada prasyarat yang perlu diselesaikan.' : 'Dua final dan prasyarat publikasi tersedia.' }}</p><ul v-if="current.problems.length" style="list-style:disc;padding-left:20px"><li v-for="p in current.problems" :key="p" class="op-caption">{{ p }}</li></ul></div><AppIcon name="shield" :size="44" /></section>
      <section class="op-panel"><h2>Catatan tindakan pengelola</h2><label class="op-field">Alasan pembukaan moderasi, penerbitan, koreksi, atau penarikan<textarea v-model="reason" maxlength="5000" /></label><label class="op-check"><input v-model="confirmed" type="checkbox" />Saya menyetujui tindakan pada peserta, paket, dan versi yang ditampilkan.</label></section>
      <section class="op-panel"><h2>Perlu diskusi antarpenguji?</h2><p class="op-caption">Buka kasus secara manual setelah dua final lengkap. Pilih indikator yang boleh dibandingkan. Publikasi yang masih aktif harus ditarik terlebih dahulu.</p><div class="op-grid"><label v-for="i in current.indicators" :key="i.id" class="op-check"><input v-model="indicators" :value="i.id" type="checkbox" /><span><strong>{{ i.id }} / {{ i.title }}</strong><br /><small>{{ i.component }}</small></span></label></div><UButton v-if="current.indicators.length" variant="soft" :disabled="current.moderation === 'open' || current.publication === 'published'" @click="openCase">Buka moderasi indikator terpilih</UButton><NuxtLink v-if="current.moderation === 'open'" to="/app/moderasi">Lanjutkan kasus moderasi yang terbuka</NuxtLink></section>
      <form class="op-panel" @submit.prevent="prepare"><h2>Susun isi untuk peserta</h2><p class="op-caption">Catatan internal tidak disalin otomatis. Koreksi publikasi membuat versi baru; versi sebelumnya tetap ada di riwayat pengelola.</p><div class="op-grid"><label class="op-field">Kekuatan<textarea v-model="content.strengths" required maxlength="5000" /></label><label class="op-field">Saran pengembangan<textarea v-model="content.improvements" required maxlength="5000" /></label></div><label v-for="c in COMPONENTS" :key="c.id" class="op-field">Feedback {{ c.label.toLowerCase() }}<textarea v-model="content.feedback[c.id]" required maxlength="5000" /></label><label class="op-check"><input v-model="content.showComponentScores" type="checkbox" />Tampilkan skor komponen dosen dan guru secara terpisah (opsional).</label><p class="op-warning">Rubrik demo. Tidak ada nilai gabungan, ambang kelulusan, atau klaim instrumen resmi UKPPPG.</p><UButton type="submit" variant="soft">Tinjau tampilan peserta</UButton></form>
      <section v-if="preview" class="op-panel" aria-label="Pratinjau publikasi peserta"><p class="eyebrow">PRATINJAU / {{ preview.participant }}</p><h2>Isi yang akan diterbitkan</h2><div class="op-grid"><div><h3>Kekuatan</h3><p class="op-note">{{ preview.strengths }}</p></div><div><h3>Pengembangan</h3><p class="op-note">{{ preview.improvements }}</p></div></div><article v-for="c in COMPONENTS" :key="c.id" class="op-divider"><h3>{{ c.label }}</h3><p class="op-note">{{ preview.feedback[c.id] }}</p><span v-for="s in preview.scores" :key="s.kind" class="op-tag">{{ s.kind }} {{ s.components.find(x => x.id === c.id)?.total }}/{{ s.components.find(x => x.id === c.id)?.maximum }}</span></article><p v-for="p in preview.problems" :key="p" class="op-error">{{ p }}</p><label class="op-check"><input v-model="confirmed" type="checkbox" />Saya sudah meninjau isi publik ini dan alasan tindakan di atas.</label><UButton :disabled="!!preview.problems.length || !confirmed" @click="publish">Terbitkan versi publikasi</UButton></section>
      <section class="op-panel"><h2>Riwayat publikasi</h2><p v-if="!history.length" class="op-caption">Belum ada publikasi untuk peserta ini.</p><article v-for="p in history" :key="p.id" class="op-divider"><div class="op-row"><h3>Versi {{ p.version }} / {{ p.status }}</h3><UButton v-if="p.status === 'published'" color="error" variant="soft" @click="withdraw(p.id)">Tarik publikasi</UButton></div><p class="op-caption">{{ formatDemoTime(p.publishedAt) }} / {{ p.rubricVersionId }}</p><p class="op-note">{{ p.reason }}</p><p v-if="p.withdrawalReason" class="op-note">Alasan penarikan: {{ p.withdrawalReason }}</p><details><summary>Lihat snapshot isi publik</summary><p class="op-note">{{ p.strengths }}</p><p class="op-note">{{ p.improvements }}</p><p v-for="c in COMPONENTS" :key="c.id" class="op-note">{{ c.label }}: {{ p.feedback[c.id] }}</p></details></article></section>
    </template><p v-else class="op-empty">Pilih peserta untuk meninjau kesiapan, moderasi, dan publikasi.</p>
  </div>
</template>
